mapper.insert:
insert into CHB_PRD_DEAL_SUB ( REGIST_SEQNO, PROD_ID, ISSUE_PARTY_ID, PROD_REGIST_CODE, ORIGINAL_VALUE, PRD_VALUE, TOTAL_VALUE, VALUE_CCY, CNY_ORL_VALUE, CNY_PRD_VALUE, CNY_TAL_VALUE, REA_YIELD, NEW_EXP_YIELD, BANK_IMP_INT, VDATE, MDATE, PURCHASE_QTY, REDEEM_QTY, BALANCE_AMT, PRD_QTY, CCY_PURCHASE, SEND_STATUS, SUBMIT_FEEDBACK_STATUS, SUMIT_SEQ, STATUS_DATE, CHB_SUBMIT_DEADLINE, SUBMIT_DEADLINE, STATUS, CREATE_USER, ORG_CODE, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, SUBMIT_TIME, REMARK, SHARE_AMT_WAN, CASH_AMT_WAN, SUBMIT_FEEDBACK_MSG, YIELD_DATE ) select HIS_NO, PROD_ID, ISSUE_PARTY_ID, PROD_REGIST_CODE, ORIGINAL_VALUE, PRD_VALUE, TOTAL_VALUE, VALUE_CCY, CNY_ORL_VALUE, CNY_PRD_VALUE, CNY_TAL_VALUE, REA_YIELD, NEW_EXP_YIELD, BANK_IMP_INT, VDATE, MDATE, PURCHASE_QTY, REDEEM_QTY, BALANCE_AMT, PRD_QTY, CCY_PURCHASE, SEND_STATUS, SUBMIT_FEEDBACK_STATUS, SUMIT_SEQ, STATUS_DATE, CHB_SUBMIT_DEADLINE, SUBMIT_DEADLINE, STATUS, CREATE_USER, ORG_CODE, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, SUBMIT_TIME, REMARK, SHARE_AMT_WAN, CASH_AMT_WAN, SUBMIT_FEEDBACK_MSG, YIELD_DATE from ( select HIS_NO, PROD_ID, ISSUE_PARTY_ID, PROD_REGIST_CODE, ORIGINAL_VALUE, PRD_VALUE, TOTAL_VALUE, VALUE_CCY, CNY_ORL_VALUE, CNY_PRD_VALUE, CNY_TAL_VALUE, REA_YIELD, NEW_EXP_YIELD, BANK_IMP_INT, VDATE, MDATE, PURCHASE_QTY, REDEEM_QTY, BALANCE_AMT, PRD_QTY, CCY_PURCHASE, SEND_STATUS, SUBMIT_FEEDBACK_STATUS, SUMIT_SEQ, STATUS_DATE, CHB_SUBMIT_DEADLINE, SUBMIT_DEADLINE, STATUS, CREATE_USER, ORG_CODE, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, SUBMIT_TIME, REMARK, SHARE_AMT_WAN, CASH_AMT_WAN, SUBMIT_FEEDBACK_MSG, YIELD_DATE, rank() over (partition by PROD_ID order by ifnull(update_time,create_time) desc) ranknum from CHB_PRD_DEAL_SUB_HIS his
